l','death','decision','deep','defense','definitely','degree','department','design','despite','development','did','die','difference','different','difficult','direct','direction','directly','director','disease','district','do','doctor','does','dog','done','door','double','doubt','down','dream','drink','drive','driving','drop','due','during','each','early','earth','easily','east','easy','eat','economic','education','effect','effort','eight','either','election','eleven','else','end','energy','enjoy','enough','entire','episode','especially','even','event','ever','every','everyone','everything','evidence','exactly','example','except','expect','experience','extra','eye','face','fact','fair','fall','family','fan','far','fast','father','favorite','fear','federal','feel','felt','female','few','field','fifth','fight','figure','film','final','finally','financial','find','fine','finish','fire','first','fish','fit','five','floor','focus','follow','food','football','for','force','foreign','forget','form','former','forward','found','four','fourth','free','friday','friend','from','front','fuck','full','fun','funny','further','future','game','gas','gay','general','generally','german','get','girl','give','given','glad','global','go','goal','god','gold','good','government','grand','great','green','ground','group','grow','growth','guess','gun','guy','had','hair','half','hand','happen','happy','hard','has','hate','have','he','head','health','hear','heart','heavy','hell','help','here','hi','high','history','hit','hold','home','hope','hospital','hot','hotel','hour','house','how','however','huge','human','hundred','hurt','husband','i','ice','idea','if','image','imagine','immediately','impact','important','in','include','income','increase','independent','individual','industry','information','inside','instead','insurance','interest','international','internet','into','involved','is','island','issue','it','job','join','judge','just','justice','keep','key','kid','kill','kind','king','know','knowledge','lack','lady','land','language','large','last','late','latest','law','lead','leader','leading','league','learn','least','leave','left','legal','less','let','letter','level','life','light','like','likely','limited','line','link','list','listen','literally','little','live','local','long','look','lord','lose','loss','lot','love','low','luck','machine','main','major','majority','make','making','man','management','manager','many','march','mark','market','marriage','master','match','material','matter','may','maybe','mean','means','media','medical','meet','meeting','member','message','middle','might','military','million','mind','minister','minute','miss','missing','model','modern','mom','moment','money','month','more','morning','most','mother','move','movement','movie','much','multiple','music','must','name','national','natural','nature','near','nearly','necessary','need','network','never','new','news','next','nice','night','nine','no','nobody','none','normal','north','not','note','nothing','notice','now','number','of','off','offer','office','officer','official','often','oil','okay','old','on','once','one','online','only','open','opening','operation','opinion','opportunity','or','order','organization','original','other','out','outside','over','overall','own','page','pain','paper','park','part','particular','particularly','party','pass','past','pay','peace','people','per','percent','perfect','performance','perhaps','period','person','personal','phone','photo','physical','pick','picture','piece','place','plan','planning','play','player','please','plus','point','police','policy','political','poor','popular','population','position','positive','possible','post','potential','power','practice','pre','present','president','press','pressure','pretty','previous','price','private','pro','probably','problem','process','product','production','professional','professor','program','project','property','protect','provide','provided','public','put','quality','question','quick','quick